// Asset download script for vk.ru page clone
// Generated by clone-website workflow
// Usage: node scripts/download-assets-vk.ru-c2886652-root-8a5edab2.mjs

import fs from 'fs';
import path from 'path';
import https from 'https';
import http from 'http';

// List of asset URLs generated by the extraction step (to be filled later)
const assets = [];

const download = (url, dest) => new Promise((resolve, reject) => {
  const client = url.startsWith('https') ? https : http;
  client.get(url, res => {
    if (res.statusCode !== 200) {
      reject(new Error(`Failed ${url}: ${res.statusCode}`));
      return;
    }
    const file = fs.createWriteStream(dest);
    res.pipe(file);
    file.on('finish', () => file.close(resolve));
  }).on('error', err => reject(err));
});

(async () => {
  const outDir = path.resolve('public/sites/vk.ru-c2886652/root-8a5edab2');
  fs.mkdirSync(outDir, { recursive: true });
  for (const url of assets) {
    try {
      const filename = path.basename(new URL(url).pathname);
      const dest = path.join(outDir, filename);
      await download(url, dest);
      console.log(`Downloaded ${url} -> ${dest}`);
    } catch (e) {
      console.error(e.message);
    }
  }
})();
